selector_to_html = {"a[href=\"#pyskyfire-ducts-volute-section-ellipticalslottedsection\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.volute_section.EllipticalSlottedSection<a class=\"headerlink\" href=\"#pyskyfire-ducts-volute-section-ellipticalslottedsection\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection._layout\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection._layout\">\n<span class=\"sig-name descname\"><span class=\"pre\">_layout</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve bore semi-axes and centre, and both tangency angles.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection.fan_origin\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection.fan_origin\">\n<span class=\"sig-name descname\"><span class=\"pre\">fan_origin</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The bore centre, which sees the whole boundary.</p><p>The area centroid does not, in general. A long throat drags it inboard\nof where the fillets begin, and from inside the slot a line to a fillet\n\u2013 which lies beyond the slot wall it is tangent to \u2013 leaves the\npassage through that wall. The bore centre is always outboard of the\nfillet tangency, so the whole boundary stays in view.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection.minimum_size\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection.minimum_size\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">minimum_size</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Half the inlet width, where the bore just spans the slot.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.volute_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">EllipticalSlottedSection</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fillet_radius</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">throat_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">4.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">VoluteSection</span></code></p><p>An elliptical bore opening into a parallel-sided inlet slot.</p><p>This is the cast pump-volute shape: an elliptical passage fed through a\nslot of fixed width <code class=\"docutils literal notranslate\"><span class=\"pre\">inlet_width</span></code>, with the junction between each slot\nwall and the bore rounded by a fillet of user-set radius. At the default\naspect ratio of one the ellipse is a circle, which is the common case.</p><p class=\"rubric\">Notes</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">size</span></code> is the semi-axis across the slot, so it plays exactly the role the\nbore radius does for a circle and the slot still fixes its floor at\n<code class=\"docutils literal notranslate\"><span class=\"pre\">inlet_width</span> <span class=\"pre\">/</span> <span class=\"pre\">2</span></code>. Writing <code class=\"docutils literal notranslate\"><span class=\"pre\">c</span></code> for it, <code class=\"docutils literal notranslate\"><span class=\"pre\">a</span> <span class=\"pre\">=</span> <span class=\"pre\">c</span> <span class=\"pre\">/</span> <span class=\"pre\">aspect</span></code> for the\nsemi-axis outward from the inlet plane, <code class=\"docutils literal notranslate\"><span class=\"pre\">b</span></code> for the inlet width, <code class=\"docutils literal notranslate\"><span class=\"pre\">r_f</span></code>\nfor the fillet radius and <code class=\"docutils literal notranslate\"><span class=\"pre\">L</span></code> for the throat length, each fillet is\nplaced by requiring it to be tangent to its slot wall and to the bore.</p><p>The fillets round a <em>reflex</em> corner \u2013 the passage opens outward as it\nleaves the slot \u2013 so each fillet centre sits outside the passage at\n<code class=\"docutils literal notranslate\"><span class=\"pre\">v</span> <span class=\"pre\">=</span> <span class=\"pre\">+/-</span> <span class=\"pre\">(b/2</span> <span class=\"pre\">+</span> <span class=\"pre\">r_f)</span></code> and touches the bore externally. Writing the\ntangency point as the ellipse parameter <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span></code> and the ellipse\u2019s outward\nunit normal there as <code class=\"docutils literal notranslate\"><span class=\"pre\">n(t)</span></code>, the fillet centre is <code class=\"docutils literal notranslate\"><span class=\"pre\">E(t)</span> <span class=\"pre\">+</span> <span class=\"pre\">r_f*n(t)</span></code>,\nand requiring its <code class=\"docutils literal notranslate\"><span class=\"pre\">v</span></code> to equal <code class=\"docutils literal notranslate\"><span class=\"pre\">-(b/2</span> <span class=\"pre\">+</span> <span class=\"pre\">r_f)</span></code> fixes <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span></code> alone:</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection._tangency\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection._tangency\">\n<span class=\"sig-name descname\"><span class=\"pre\">_tangency</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">semi_u</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">semi_v</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Ellipse parameter where each fillet touches the bore.</p><p>Solved numerically rather than in closed form because the offset curve\nof an ellipse is not an ellipse. The bracket is fixed and its ends are\nknown to straddle the root: at <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span> <span class=\"pre\">=</span> <span class=\"pre\">-pi</span></code> the residual is <code class=\"docutils literal notranslate\"><span class=\"pre\">h</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">0</span></code>,\nand at <code class=\"docutils literal notranslate\"><span class=\"pre\">t</span> <span class=\"pre\">=</span> <span class=\"pre\">-pi/2</span></code> it is <code class=\"docutils literal notranslate\"><span class=\"pre\">b/2</span> <span class=\"pre\">-</span> <span class=\"pre\">c</span> <span class=\"pre\">&lt;=</span> <span class=\"pre\">0</span></code>. That second end is an\nequality exactly when the bore has closed down onto the slot, and there\nthe residual meets zero tangentially \u2013 a double root, which is why\nthis bisects rather than reaching for faster convergence.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection.inboard_overhang\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection.inboard_overhang\">\n<span class=\"sig-name descname\"><span class=\"pre\">inboard_overhang</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>How far the bore reaches inboard of the inlet plane [m].</p><p>Zero for a fully external volute, positive for an intermediate one.</p></dd>", "a[href=\"#pyskyfire.ducts.volute_section.EllipticalSlottedSection.boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.volute_section.EllipticalSlottedSection.boundary\">\n<span class=\"sig-name descname\"><span class=\"pre\">boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Counterclockwise boundary pieces for each size and aspect.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
